'use strict';
const net=require('node:net'),crypto=require('node:crypto');
const secret=()=>crypto.randomBytes(32).toString('hex');
function endpoint(value,{test=false}={}){const u=new URL(value);if((u.protocol!=='https:'&&!(test&&u.protocol==='http:'&&u.hostname==='127.0.0.1'))||u.username||u.password||u.search||u.hash||u.pathname!=='/')throw Error('Use the HTTPS origin of your Boralances relay.');return u.origin;}
function encodeInvite(invite){return 'bora1.'+Buffer.from(JSON.stringify(invite)).toString('base64url');}
function decodeInvite(text,options){if(typeof text!=='string'||text.length>2048||!text.startsWith('bora1.'))throw Error('Paste a Boralances friend invite.');let item;try{item=JSON.parse(Buffer.from(text.slice(6),'base64url'));}catch{throw Error('Invalid friend invite.');}item.endpoint=endpoint(item.endpoint,options);if(!/^[a-f0-9]{32}$/.test(item.room)||!/^[a-f0-9]{64}$/.test(item.key)||typeof item.name!=='string'||item.name.length>80||typeof item.minecraft!=='string'||!/^[0-9.a-z-]{1,32}$/i.test(item.minecraft))throw Error('Invalid friend invite.');return {endpoint:item.endpoint,room:item.room,key:item.key,name:item.name,minecraft:item.minecraft};}
class Relay {
 constructor({WebSocketImpl=globalThis.WebSocket,test=false,onStatus=()=>{}}={}){this.WS=WebSocketImpl;this.test=test;this.onStatus=onStatus;this.sockets=new Set();this.streams=new Map();this.closed=false;}
 connect(invite,role,hostKey){return new Promise((resolve,reject)=>{const origin=endpoint(invite.endpoint,{test:this.test}).replace(/^http/,'ws'),ws=new this.WS(origin+'/room/'+invite.room+'/'+role);ws.binaryType='arraybuffer';this.sockets.add(ws);let done=false;const timer=setTimeout(()=>{ws.close();if(!done)reject(Error('Relay did not respond.'));},12000);ws.addEventListener('open',()=>ws.send(JSON.stringify({type:'auth',key:role==='host'?hostKey:invite.key,...(role==='host'?{joinKey:invite.key}:{})})));ws.addEventListener('message',event=>{if(typeof event.data!=='string')return;let reply;try{reply=JSON.parse(event.data);}catch{return;}if(reply.type==='authenticated'&&!done){done=true;clearTimeout(timer);resolve(ws);}});ws.addEventListener('error',()=>{if(!done){clearTimeout(timer);reject(Error('Could not connect to the friends relay.'));}});ws.addEventListener('close',()=>{this.sockets.delete(ws);clearTimeout(timer);if(!done)reject(Error('Host unavailable or invite expired.'));});});}
 async host({endpoint:origin,port,name,minecraft}){if(!Number.isInteger(port)||port<1024||port>65535)throw Error('Invalid local game port.');const invite={endpoint:endpoint(origin,{test:this.test}),room:crypto.randomBytes(16).toString('hex'),key:secret(),name:String(name).slice(0,80),minecraft},key=secret(),ws=await this.connect(invite,'host',key);const close=id=>{const socket=this.streams.get(id);this.streams.delete(id);socket?.destroy();};ws.addEventListener('message',event=>{try{if(typeof event.data==='string'){const control=JSON.parse(event.data);if(control.type==='open'&&Number.isInteger(control.id)&&this.streams.size<8){const id=control.id,socket=net.connect({host:'127.0.0.1',port});socket.setNoDelay(true);this.streams.set(id,socket);socket.on('data',data=>{for(let i=0;i<data.length;i+=65536){const part=data.subarray(i,i+65536),frame=Buffer.allocUnsafe(part.length+4);frame.writeUInt32BE(id,0);part.copy(frame,4);if(ws.bufferedAmount>4*1024*1024)return socket.destroy();if(ws.readyState===1)ws.send(frame);}});socket.on('error',()=>socket.destroy());socket.on('close',()=>{this.streams.delete(id);if(ws.readyState===1)ws.send(JSON.stringify({type:'close',id}));});}else if(control.type==='close')close(control.id);}else{const frame=Buffer.from(event.data);if(frame.length<4)return;const socket=this.streams.get(frame.readUInt32BE(0));if(socket){if(socket.writableLength>4*1024*1024)return socket.destroy();socket.write(frame.subarray(4));}}}catch{ws.close();}});ws.addEventListener('close',()=>{for(const id of this.streams.keys())close(id);this.onStatus('Host relay disconnected. Create a new invite to reconnect.');});this.invite=invite;this.onStatus('Friends relay connected. Invites expire after two hours.');return encodeInvite(invite);}
 async join(text){const invite=decodeInvite(text,{test:this.test});const pending=new Set();this.server=net.createServer(socket=>{pending.add(socket);socket.setNoDelay(true);socket.pause();this.connect(invite,'join').then(ws=>{if(socket.destroyed){ws.close();return;}ws.addEventListener('message',event=>{if(typeof event.data==='string')return;if(socket.writableLength>4*1024*1024)return socket.destroy();socket.write(Buffer.from(event.data));});ws.addEventListener('close',()=>socket.destroy());socket.on('data',data=>{if(ws.bufferedAmount>4*1024*1024)return socket.destroy();for(let i=0;i<data.length;i+=65536)if(ws.readyState===1)ws.send(data.subarray(i,i+65536));});socket.on('close',()=>{pending.delete(socket);ws.close();});socket.resume();}).catch(()=>socket.destroy());});await new Promise((resolve,reject)=>{this.server.once('error',reject);this.server.listen(0,'127.0.0.1',resolve);});this.pending=pending;return {host:'127.0.0.1',port:this.server.address().port,minecraft:invite.minecraft,name:invite.name};}
 close(){this.closed=true;this.server?.close();for(const s of this.pending||[])s.destroy();for(const s of this.streams.values())s.destroy();for(const ws of this.sockets)ws.close();this.streams.clear();this.sockets.clear();}
}
module.exports={Relay,endpoint,encodeInvite,decodeInvite};
